fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since `a` is guaranteed non‐empty, `.min()` will return Some(&i8).
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Similarly for `.max()`.
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // q is assumed to be in [0, 100].
    debug_assert!(q >= 0 && q <= 100, "quantile must be between 0 and 100");

    // Sort in place.  We only need the ordering, not stability.
    a.sort_unstable();

    let n = a.len();
    // For n >= 1, (n - 1) is well‐defined.
    // We map q=0 → idx=0, q=100 → idx=n-1.
    let idx = (q as usize) * (n - 1) / 100;

    a[idx]
}

